WITH p AS (SELECT DISTINCT p.subject_id FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age = 95 AND a.admission_type = 'Hospitalized' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2019 AND 2020 AND p.anchor_year BETWEEN 90 AND 100 AND (SELECT COUNT(*) FROM prescriptions pr WHERE pr.drug_type = 'Thiazide-like' AND pr.starttime <= a.admittime AND pr.stoptime >= a.dischtime) > 0), d AS (SELECT (stoptime - starttime) AS duration FROM prescriptions WHERE drug_type = 'Thiazide-like' AND starttime <= (SELECT MIN(admittime) FROM admissions WHERE subject_id IN (SELECT subject_id FROM p)) AND stoptime >= (SELECT MAX(dischtime) FROM admissions WHERE subject_id IN (SELECT subject_id FROM p))) SELECT (percentile_cont(0.75) within GROUP (ORDER BY duration) - percentile_cont(0.25) within GROUP (ORDER BY duration)) AS interquartile_range FROM d;